package cn.yueji.balance;

import android.view.*;
import android.widget.*;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.uiautomator.*;
import org.junit.*;
import org.junit.runner.RunWith;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;

@RunWith(AndroidJUnit4.class)
public class V4713UiTest {
    final V4711UiTest old=new V4711UiTest();final YuejiTest t=old.t;final V43UiTest h=old.h;
    @Before public void before(){old.before();}
    @After public void after()throws Exception{old.after();}
    void tap(String text){old.old.tap(text);}
    void shot(String name){old.old.shot("v4713-"+name+".png");}
    Ledger.Entry add(Ledger.Data d,String kind,long amount,String time,long account){Ledger.Entry e=new Ledger.Entry(d.nextId(),Ledger.INCOME.equals(kind),amount,LocalDateTime.parse(time),"合成记录","",account);e.kind=kind;e.category="其他";e.cashLinked=account>0;d.entries.add(e);return e;}
    FundProfile limit(String amount){FundProfile p=new FundProfile();p.readDailyLimit("<td>日累计申购限额</td><td>"+amount+"</td>","");return p;}
    Ledger.Data colours(){Ledger.Data d=old.sample();add(d,Ledger.INCOME,50000,"2026-10-10T10:00",1);add(d,Ledger.LARGE,20000,"2026-10-11T10:00",1);Ledger.Entry e=add(d,Ledger.REIMBURSE,80000,"2026-10-12T10:00",1);Ledger.Receipt r=new Ledger.Receipt(80000,LocalDateTime.parse("2026-10-13T10:00"));r.accountId=1;r.cashLinked=true;e.receipts.add(r);e.status=e.reimbursementStatus();FundTransactions.save(d,0,0,"006431",100000,0,LocalDateTime.of(2026,10,14,12,0),null,"离线",false,true,1,new TradingCalendar());return d;}
    void assertColour(String text,int colour){TextView v=(TextView)t.findText(t.app.body,text);assertNotNull(text,v);assertEquals(text,colour,v.getCurrentTextColor());}
    @Test public void accountAmountsUseTypeColoursAndRetainSignedValues(){t.start(colours());old.history(1);t.ui(()->{assertColour("+¥ 500.00",Ui.RED);assertColour("-¥ 200.00",Ui.GREEN);assertColour("-¥ 800.00",Ui.BLUE);assertColour("+¥ 800.00",Ui.BLUE);assertColour("-¥ 1,000.00",Ui.ORANGE);assertColour("¥ 10,000.00",Ui.RECORD_PURPLE);});shot("account-colours");}
    @Test public void blueAppThemeDoesNotChangePurpleBalanceMeaning(){t.start(colours());t.ui(()->t.app.getPreferences(0).edit().putInt("palette",1).commit());old.history(1);t.ui(()->{assertNotEquals(Ui.PURPLE,Ui.RECORD_PURPLE);assertColour("¥ 10,000.00",Ui.RECORD_PURPLE);assertColour("+¥ 500.00",Ui.RED);});shot("blue-theme-purple-balance");}
    @Test public void rightArrowStartsWithTrendThenCompositionThenAccounts(){t.start(old.sample());t.ui(()->{assertEquals(2,t.app.assetTab);h.desc(t.app.body,"下一个资产视图").performClick();assertEquals(1,t.app.assetTab);assertNotNull(h.first(t.app.body,AssetTrendChart.class));h.desc(t.app.body,"下一个资产视图").performClick();assertEquals(0,t.app.assetTab);assertNotNull(h.first(t.app.body,AssetDonut.class));h.desc(t.app.body,"下一个资产视图").performClick();assertEquals(2,t.app.assetTab);assertNotNull(h.desc(t.app.body,"账户支付宝"));h.desc(t.app.body,"上一个资产视图").performClick();assertEquals(0,t.app.assetTab);});shot("asset-cycle");}
    Ledger.Data months(){Ledger.Data d=old.sample();YearMonth now=YearMonth.now();add(d,Ledger.INCOME,50000,now.atDay(1).atStartOfDay().toString(),0);add(d,Ledger.INCOME,30000,now.minusMonths(2).atDay(3).atStartOfDay().toString(),0);add(d,Ledger.LARGE,20000,now.minusMonths(1).atDay(3).atStartOfDay().toString(),0);add(d,Ledger.REIMBURSE,40000,now.minusMonths(3).atDay(3).atStartOfDay().toString(),0);return d;}
    @Test public void flowCardsShowCurrentAndNearestEarlierMonthsInMatchingColours(){t.start(months());t.ui(()->{t.app.openTab(MainActivity.TAB_FLOW);assertColour("本月 ¥ 500.00",Ui.RED);assertColour("上月 ¥ 200.00",Ui.GREEN);TextView income=(TextView)h.desc(t.app.body,"收支前月income"),reimburse=(TextView)h.desc(t.app.body,"收支前月reimburse");assertEquals(YearMonth.now().minusMonths(2).getMonthValue()+"月 ¥ 300.00",income.getText().toString());assertEquals(YearMonth.now().minusMonths(3).getMonthValue()+"月 ¥ 400.00",reimburse.getText().toString());assertEquals(Ui.BLUE,reimburse.getCurrentTextColor());});shot("flow-months");}
    @Test public void recordCardsAlsoUseBlueReimbursementAndGreenExpense(){t.start(colours());t.ui(()->{t.app.go("reimburse_detail");assertColour("¥ 800.00",Ui.BLUE);t.app.go("large_detail");assertColour("¥ 200.00",Ui.GREEN);});shot("expense-colour");}
    Ledger.Data owned(){Ledger.Data d=t.sample();d.settings.autoRefresh=false;for(Ledger.Fund f:d.funds){f.profile.established="2020-01-01";f.profile.scale="1亿元";f.profile.updated=FundEngine.now().toLocalDate().toString();}return d;}
    void detail(){t.ui(()->{t.app.fundFocus=t.app.data.funds.get(0).id;t.app.go("fund_detail");});}
    @Test public void greyMoreAsksBeforeAddingAndDoesNotCreateAnyPurchase(){Ledger.Data d=owned();int buys=d.funds.get(0).buys.size(),entries=d.entries.size();t.start(d);detail();t.ui(()->{TextView more=(TextView)h.desc(t.app.body,"基金更多");assertEquals(Ui.FAINT,more.getCurrentTextColor());assertTrue(more.isEnabled());more.performClick();});assertNotNull(t.device.wait(Until.findObject(By.text("加入自选基金？")),2000));shot("more-confirm");tap("取消");assertEquals(0,t.store.load().watchFunds.size());t.ui(()->h.desc(t.app.body,"基金更多").performClick());tap("加入并查看");assertEquals("watch_detail",t.app.page);assertEquals(1,t.store.load().watchFunds.size());assertEquals(buys,t.store.load().funds.get(0).buys.size());assertEquals(entries,t.store.load().entries.size());shot("more-watch-detail");}
    @Test public void alreadyExplicitWatchMoreOpensDirectlyAndBackReturnsToOwnedDetail(){Ledger.Data d=owned();d.watchFunds.add(WatchAnalytics.owned(d.funds.get(0)));t.start(d);detail();t.ui(()->{TextView more=(TextView)h.desc(t.app.body,"基金更多");assertEquals(Ui.ACCENT,more.getCurrentTextColor());more.performClick();});assertEquals("watch_detail",t.app.page);assertEquals(1,t.store.load().watchFunds.size());t.device.pressBack();t.instrument.waitForIdleSync();assertEquals("fund_detail",t.app.page);}
    Ledger.Data limited(){Ledger.Data d=old.sample();Ledger.WatchFund w=new Ledger.WatchFund("161125","合成限购基金");w.profile.merge(limit("20元"));w.profile.established="2020-01-01";w.profile.scale="1亿元";w.profile.updated=FundEngine.now().toLocalDate().toString();w.fundType="QDII-股票指数";d.watchFunds.add(w);Ledger.WatchGroup g=new Ledger.WatchGroup(d.nextId(),"原分组");g.codes.add(w.code);d.watchGroups.add(g);return d;}
    @Test public void dailyLimitIsBlueAfterCodeAndSystemGroupContainsIt(){t.start(limited());t.ui(()->{t.app.watchFocus="161125";t.app.go("watch_detail");TextView label=(TextView)h.desc(t.app.body,"基金每日限购");assertTrue(label.getText().toString().contains("限制单日买入20元"));assertEquals(Ui.BLUE,label.getCurrentTextColor());assertTrue(WatchGroups.member(t.app.data,"161125",WatchGroups.LIMITED));assertFalse(WatchGroups.member(t.app.data,"161125","原分组"));});shot("limit-label");t.ui(()->{t.app.go("fund_watchlist");assertNotNull(t.findText(t.app.body,"定投(1)"));});shot("automatic-limit-group");}
    @Test public void limitedFundCanBeAddedOutButAutomaticGroupCannotBePicked(){t.start(limited());t.ui(()->{t.app.go("fund_watchlist");t.app.watchScreens.activeGroup=WatchGroups.LIMITED;t.app.watchScreens.addToGroup(t.app.watchScreens.find("161125"),t.app.data.watchGroups.get(0).id,true);assertTrue(WatchGroups.member(t.app.data,"161125",WatchGroups.LIMITED));assertTrue(WatchGroups.member(t.app.data,"161125","原分组"));t.app.watchScreens.groupPicker(Collections.singleton("161125"),false);});assertNull(t.device.findObject(By.text("定投")));UiObject2 remove=t.device.findObject(By.text("是否从本组移除（持有/定投为自动分组，仍保留）"));assertNotNull(remove);assertFalse(remove.isEnabled());shot("limited-copy-out");tap("取消");}
    @Test public void limitedOwnedFundLeavesOtherWatchViewsWithoutChangingHolding(){Ledger.Data d=owned();Ledger.Fund fund=d.funds.get(0);fund.profile.merge(limit("10元"));d.watchFunds.add(WatchAnalytics.owned(fund));long total=d.total();int buys=fund.buys.size();t.start(d);t.ui(()->{t.app.go("fund_watchlist");assertTrue(WatchGroups.held(t.app.data,fund.code));assertFalse(WatchGroups.member(t.app.data,fund.code,"持有"));assertFalse(WatchGroups.member(t.app.data,fund.code,"全部"));assertTrue(WatchGroups.member(t.app.data,fund.code,WatchGroups.LIMITED));});assertEquals(total,t.store.load().total());assertEquals(buys,t.store.load().funds.get(0).buys.size());}
    @Test public void customGroupCannotUseReservedSystemName(){t.start(limited());t.ui(()->{t.app.go("fund_watchlist");t.app.watchScreens.groupEditor(null);});UiObject2 name=t.device.wait(Until.findObject(By.clazz(EditText.class)),2000);assertNotNull(name);name.setText("定投");tap("保存");assertNotNull(t.device.wait(Until.findObject(By.textContains("不能使用全部、持有或定投")),2000));assertEquals(1,t.store.load().watchGroups.size());}
    @Test public void newTransferDefaultsToAllCashAndChangingSourceRefillsIt(){Ledger.Data d=old.sample();add(d,Ledger.INCOME,50000,"2026-10-10T10:00",1);t.start(d);old.history(1);t.ui(()->t.findText(t.app.body,"转账").performClick());UiObject2 amount=t.device.wait(Until.findObject(By.desc("转账金额")),2000);assertEquals("10500.00",amount.getText());amount.setText("123.45");t.device.findObject(By.desc("转出账户")).click();tap("微信");assertEquals("5000.00",t.device.wait(Until.findObject(By.desc("转账金额")),2000).getText());t.device.findObject(By.desc("转账金额")).setText("222.22");t.device.findObject(By.desc("转入账户")).click();tap("支付宝");assertEquals("222.22",t.device.findObject(By.desc("转账金额")).getText());shot("transfer-default");tap("取消");assertTrue(t.store.load().transfers.isEmpty());}
    @Test public void transferFromJustCreatedAccountUsesCurrentTimeAndConservesTotal(){Ledger.Data d=old.sample();LocalDateTime now=LocalDateTime.now().minusSeconds(1);d.snapshots.clear();for(Ledger.Account a:d.accounts){a.created=now;MonthLedger.updateAccount(d,a.id,now,a.opening);}t.start(d);old.history(1);t.ui(()->t.findText(t.app.body,"转账").performClick());t.device.findObject(By.desc("转入账户")).click();tap("微信");tap("保存转账");Ledger.Data saved=t.store.load();assertEquals(1,saved.transfers.size());assertFalse(saved.transfers.get(0).at.isBefore(now));assertEquals(0,saved.balance(saved.accounts.get(0)));assertEquals(1500000,saved.total());}
    @Test public void editingTransferKeepsItsOriginalAmountInsteadOfCurrentAllCash(){Ledger.Data d=old.sample();Ledger.Transfer transfer=TransferLedger.save(d,0,1,2,150000,LocalDateTime.of(2026,10,5,12,0),"");t.start(d);t.ui(()->new TransferScreens(t.app).open(1,TransferLedger.find(t.app.data,transfer.id)));assertEquals("1500.00",t.device.wait(Until.findObject(By.desc("转账金额")),2000).getText());tap("取消");}
    @Test public void flowSummaryAndSignedAmountsFitShortScreenLargeFontsAndDarkMode()throws Exception{try{for(int appearance:new int[]{1,2}){t.device.executeShellCommand("wm size 1080x1920");t.device.executeShellCommand("wm density 420");t.device.executeShellCommand("settings put system font_scale 1.3");t.start(months());t.ui(()->{t.app.getPreferences(0).edit().putInt("appearance",appearance).commit();t.app.openTab(MainActivity.TAB_FLOW);});t.device.waitForIdle();new V4710UiTest().assertNumbers(t.app.body);t.ui(()->{FinanceChart chart=t.app.findFinanceChart(t.app.body);assertTrue("chart height="+chart.getHeight(),chart.getHeight()>=t.app.dp(60));});shot("months-large-font-"+appearance);t.start(colours());t.ui(()->t.app.getPreferences(0).edit().putInt("appearance",appearance).commit());old.history(1);t.device.waitForIdle();new V4710UiTest().assertNumbers(t.app.body);shot("colours-large-font-"+appearance);}}finally{t.device.executeShellCommand("wm size reset");t.device.executeShellCommand("wm density reset");t.device.executeShellCommand("settings put system font_scale 1.0");}}
    @Test public void staleFormSavePreservesNewerLimitMetadata(){Ledger.Data d=limited();t.start(d);Ledger.Data stale=t.app.copy(),fresh=t.store.load();FundProfile info=limit("无限额");info.dailyLimitChecked=FundEngine.now().plusSeconds(1).toString();WatchlistScreens.applyProfile(fresh,"161125",info);t.store.save(fresh);t.ui(()->t.app.commit(stale));assertFalse(WatchGroups.member(t.store.load(),"161125",WatchGroups.LIMITED));assertTrue(t.store.load().watchFunds.get(0).profile.dailyLimitConfirmed);}
    @Test public void listChecksEveryCodeOnceAndGroupsOnlyExplicitLimitedResults()throws Exception{Ledger.Data d=old.sample();d.watchFunds.add(new Ledger.WatchFund("000001","合成限购"));d.watchFunds.add(new Ledger.WatchFund("000002","合成不限购"));t.start(d);java.util.concurrent.atomic.AtomicInteger calls=new java.util.concurrent.atomic.AtomicInteger();t.ui(()->{t.app.watchScreens.limitFetcher=code->{calls.incrementAndGet();return limit(code.equals("000001")?"10元":"无限额");};t.app.go("fund_watchlist");});long until=android.os.SystemClock.uptimeMillis()+5000;while(android.os.SystemClock.uptimeMillis()<until&&!WatchGroups.profile(t.store.load(),"000002").dailyLimitConfirmed)android.os.SystemClock.sleep(50);t.instrument.waitForIdleSync();assertEquals(2,calls.get());assertTrue(WatchGroups.member(t.store.load(),"000001",WatchGroups.LIMITED));assertFalse(WatchGroups.member(t.store.load(),"000002",WatchGroups.LIMITED));t.ui(()->{t.app.render();t.app.render();});android.os.SystemClock.sleep(100);assertEquals(2,calls.get());}
    FundProfile liveLimit(String code)throws Exception{Exception last=null;for(int i=0;i<3;i++){try{return FundClient.dailyLimit(code);}catch(java.io.IOException e){last=e;android.os.SystemClock.sleep(200);}}throw last;}
    @Test public void publicLimitEndpointProvidesExplicitDailyEvidence()throws Exception{FundProfile cap=liveLimit("161125"),other=liveLimit("000001");assertTrue(cap.dailyLimitConfirmed);assertTrue(other.dailyLimitConfirmed);cap.validate();other.validate();Ledger.Data d=old.sample();Ledger.WatchFund w=new Ledger.WatchFund("161125","公开接口验证");w.profile.merge(cap);d.watchFunds.add(w);LedgerStore.validate(d);assertEquals(cap.limited(),WatchGroups.member(d,w.code,WatchGroups.LIMITED));assertTrue(d.entries.isEmpty());}
}
